insert into fdh_source_registry (source_key, source_name, source_category, source_reference_note, accessed_at, notes) values
  ($lit$iso18245_mcc_public_reference$lit$, $lit$ISO 18245 Merchant Category Codes — public payment-network reference lists$lit$, $lit$official_mcc_reference$lit$, $lit$Publicly documented MCC lists published by card-network reference materials (e.g. Visa/Mastercard merchant category tables) and cross-industry MCC directories$lit$, $lit$2026-08-21$lit$, $lit$Used for MCC code + standard description only. No proprietary per-merchant mapping was copied — mappings to FHIP categories are FHIP design decisions.$lit$),
  ($lit$au_institution_public_websites$lit$, $lit$Australian financial institution official websites and public regulatory disclosures$lit$, $lit$institution_official_website$lit$, $lit$Official corporate/brand websites and APRA-authorised-ADI public register$lit$, $lit$2026-08-21$lit$, $lit$Used for institution legal names, brand names, and ownership structure only. No customer data of any kind.$lit$),
  ($lit$in_institution_public_websites$lit$, $lit$Indian financial institution official websites and RBI public bank list$lit$, $lit$institution_official_website$lit$, $lit$Official corporate/brand websites and RBI-published scheduled commercial bank list$lit$, $lit$2026-08-21$lit$, $lit$Used for institution legal names, brand names, and ownership structure only. No customer data of any kind.$lit$),
  ($lit$au_public_merchant_information$lit$, $lit$Australian merchant/retailer public company information$lit$, $lit$public_company_information$lit$, $lit$Official corporate websites, ASX/ASIC public company records, publicly reported store-brand information$lit$, $lit$2026-08-21$lit$, $lit$Used for merchant identity (legal/trading name, sector, website domain) only.$lit$),
  ($lit$in_public_merchant_information$lit$, $lit$Indian merchant/retailer/platform public company information$lit$, $lit$public_company_information$lit$, $lit$Official corporate websites and publicly reported company/brand information$lit$, $lit$2026-08-21$lit$, $lit$Used for merchant identity (legal/trading name, sector, website domain) only.$lit$),
  ($lit$au_government_payment_public_info$lit$, $lit$Services Australia / ATO public payment-description information$lit$, $lit$government_official_source$lit$, $lit$Publicly published descriptions of Centrelink/Services Australia payment types and ATO refund/payment reference conventions$lit$, $lit$2026-08-21$lit$, $lit$Used to describe generic AU government payment/refund categories. No individual-level benefit data.$lit$),
  ($lit$in_government_payment_public_info$lit$, $lit$EPFO / Income Tax Department India public payment-description information$lit$, $lit$government_official_source$lit$, $lit$Publicly published descriptions of EPFO contribution/withdrawal conventions and income-tax refund reference conventions$lit$, $lit$2026-08-21$lit$, $lit$Used to describe generic India government/retirement payment categories. No individual-level benefit data.$lit$),
  ($lit$au_payment_rail_public_documentation$lit$, $lit$Australian payment-system public documentation (BPAY, PayID/NPP, EFTPOS)$lit$, $lit$industry_public_documentation$lit$, $lit$Publicly available scheme documentation describing BPAY, Osko/PayID (New Payments Platform) and EFTPOS as payment mechanisms$lit$, $lit$2026-08-21$lit$, $lit$Used to describe payment RAIL structure only — never as an economic category.$lit$),
  ($lit$in_payment_rail_public_documentation$lit$, $lit$Indian payment-system public documentation (UPI/NPCI, IMPS, NEFT, RTGS)$lit$, $lit$industry_public_documentation$lit$, $lit$Publicly available NPCI/RBI documentation describing UPI, IMPS, NEFT and RTGS as payment mechanisms$lit$, $lit$2026-08-21$lit$, $lit$Used to describe payment RAIL structure only — never as an economic category.$lit$),
  ($lit$fhip_taxonomy_design$lit$, $lit$FHIP-designed category/subcategory taxonomy$lit$, $lit$fhip_design_decision$lit$, $lit$Internal FHIP design, informed by the personal-finance/banking-classification research summarised in FDH2_RESEARCH_EVIDENCE.md$lit$, $lit$2026-08-21$lit$, $lit$Structural taxonomy decisions (families, subcategories, economic-type assignment, essential/discretionary defaults) are FHIP-owned design, not a copied third-party taxonomy.$lit$),
  ($lit$personal_finance_classification_research$lit$, $lit$Published personal-finance/banking transaction-classification concepts$lit$, $lit$industry_public_documentation$lit$, $lit$Publicly documented concepts of category taxonomy structure, merchant normalisation, recurring/subscription handling, transfer treatment and user-rule precedence, as commonly described in personal-finance-software product documentation and payment-network category literature$lit$, $lit$2026-08-21$lit$, $lit$Used for CONCEPTS only (how such systems are commonly structured) — no proprietary source code, database or closed dataset was copied.$lit$)
insert into fdh_economic_transaction_types (economic_type, display_name, description) values
  ($lit$income$lit$, $lit$Income$lit$, $lit$Money received that increases household resources — salary, wages, business income, rental income, interest, dividends, government benefits, pensions and similar.$lit$),
  ($lit$expense$lit$, $lit$Expense$lit$, $lit$A household outflow for goods, services or living costs.$lit$),
  ($lit$transfer$lit$, $lit$Transfer$lit$, $lit$A movement of money between the household's own accounts, or a settlement such as a credit-card bill payment. Not income or expense in itself.$lit$),
  ($lit$investment$lit$, $lit$Investment$lit$, $lit$A movement of money into or related to an investment or retirement-contribution activity.$lit$),
  ($lit$debt_principal$lit$, $lit$Debt principal repayment$lit$, $lit$The portion of a loan repayment that reduces the outstanding principal balance.$lit$),
  ($lit$debt_interest$lit$, $lit$Debt interest$lit$, $lit$Interest charged on a loan or credit facility.$lit$),
  ($lit$refund$lit$, $lit$Refund / reversal$lit$, $lit$Money returned for a prior purchase, or a reversed/charged-back transaction.$lit$),
  ($lit$asset_purchase$lit$, $lit$Asset purchase$lit$, $lit$Money used to acquire an investment or other recorded asset.$lit$),
  ($lit$asset_sale$lit$, $lit$Asset sale$lit$, $lit$Money received from disposing of an investment or other recorded asset.$lit$),
  ($lit$tax$lit$, $lit$Tax$lit$, $lit$A tax payment or a tax-related government charge.$lit$),
  ($lit$fee$lit$, $lit$Fee$lit$, $lit$A bank, card or account fee or charge, distinct from interest.$lit$),
  ($lit$cash_withdrawal$lit$, $lit$Cash withdrawal$lit$, $lit$Cash withdrawn from an account via ATM or branch. Not automatically household consumption — what the cash was later used for is unknown.$lit$),
  ($lit$unknown$lit$, $lit$Unknown$lit$, $lit$Not yet resolved to any of the above. The default state until a classification is made.$lit$)
