  ($lit$cash_withdrawal$lit$, $lit$Cash Withdrawal$lit$, $lit$Cash withdrawn via ATM or branch. Not automatically household consumption — what the cash is later used for is unknown to FDH.$lit$, $lit$cash_withdrawal$lit$, array['AU','IN']::char(2)[], $lit$not_applicable$lit$, $lit$not_applicable$lit$, false, false, false, false, $lit$cash_withdrawal.general$lit$, 270, $lit$banknotes$lit$, $lit$fhip_taxonomy_design$lit$),
